// Codec library (src/codec) unit tests: the decoders against vectors from
// independent encoders, their behaviour on truncated, corrupted and
// over-long input, the checksums against their published check values, and
// the dispatch table.
//
// vectors.h is generated by make_vectors.py (zlib, libbz2 and liblzma
// through Python, Apple's LZFSE encoder through pyliblzfse); the data each
// vector decodes to is regenerated by vec_gen() (vec_gen.h), the same
// generator.
// The DEFLATE encoder is covered by the udif_writer suite, the resumable
// inflater by the peeler suite and ADC by the ndif suite.

#include "codec.h"
#include "test_assert.h"
#include "vec_gen.h"
#include "vectors.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N_VECTORS (sizeof(k_vectors) / sizeof(k_vectors[0]))

// The largest encoding the exhaustive truncation and corruption tests walk.
#define EXHAUSTIVE_MAX 4096

// ---- data ----------------------------------------------------------------

// A copy of `n` bytes, so a test may change them.
static uint8_t *dup_bytes(const uint8_t *p, size_t n) {
    uint8_t *b = malloc(n ? n : 1);
    ASSERT_TRUE(b != NULL);
    memcpy(b, p, n);
    return b;
}

// Report the vector a failing assertion is about.
static void note(const vector_t *v, const char *what) {
    fprintf(stderr, "       %s: %s\n", v->name, what);
}

// ---- decoding the vectors --------------------------------------------------

// Every vector decodes to its data: with the exact capacity, with room to
// spare, and -- one byte short -- not at all.
TEST(vectors_decode_exactly) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len + 64);
        ASSERT_TRUE(out != NULL);

        int64_t n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len);
        if (n != (int64_t)v->len)
            note(v, codec_strerror(n));
        ASSERT_EQ_INT((int)v->len, (int)n);
        ASSERT_TRUE(memcmp(out, want, v->len) == 0);

        memset(out, 0xA5, v->len + 64);
        n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len + 64);
        ASSERT_EQ_INT((int)v->len, (int)n);
        ASSERT_TRUE(memcmp(out, want, v->len) == 0);
        for (size_t k = v->len; k < v->len + 64; k++)
            ASSERT_TRUE(out[k] == 0xA5); // nothing written past the data

        if (v->len) {
            n = codec_decode((codec_id_t)v->codec, v->enc, v->enc_len, out, v->len - 1);
            if (n != CODEC_ERR_OVERFLOW)
                note(v, "one byte short");
            ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)n);
        }
        free(out);
        free(want);
    }
}

// Every proper prefix of an encoding either fails or -- where the format
// lets a stream end early, as zlib's optional trailer does -- decodes to
// exactly the data.  Never a wrong success, never a read past the prefix
// (each prefix is its own allocation, so ASan sees any overrun).
TEST(truncation_fails_cleanly) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if (v->enc_len > EXHAUSTIVE_MAX)
            continue;
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len + 1);
        ASSERT_TRUE(out != NULL);
        for (size_t cut = 0; cut < v->enc_len; cut++) {
            uint8_t *part = dup_bytes(v->enc, cut);
            int64_t n = codec_decode((codec_id_t)v->codec, part, cut, out, v->len);
            if (n >= 0) {
                if (n != (int64_t)v->len || memcmp(out, want, v->len) != 0)
                    note(v, "a truncated stream decoded to the wrong data");
                ASSERT_EQ_INT((int)v->len, (int)n);
                ASSERT_TRUE(memcmp(out, want, v->len) == 0);
            }
            free(part);
        }
        free(out);
        free(want);
    }
}

// One flipped bit at every byte of an encoding never crashes the decoder or
// writes past the buffer; the result is an error or some output of at most
// the capacity.  (Not every flip is detectable: LZFSE and raw DEFLATE carry
// no checksum.)
TEST(corruption_is_contained) {
    uint32_t x = 12345;
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if (v->enc_len > EXHAUSTIVE_MAX)
            continue;
        size_t cap = v->len + 16;
        uint8_t *out = malloc(cap);
        ASSERT_TRUE(out != NULL);
        for (size_t at = 0; at < v->enc_len; at++) {
            uint8_t *bad = dup_bytes(v->enc, v->enc_len);
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            bad[at] ^= (uint8_t)(1u << (x & 7));
            int64_t n = codec_decode((codec_id_t)v->codec, bad, v->enc_len, out, cap);
            ASSERT_TRUE(n <= (int64_t)cap);
            ASSERT_TRUE(n >= CODEC_ERR_ARG);
            free(bad);
        }
        free(out);
    }
}

// Streams whose framing checksums catch any single flipped bit: bzip2's
// block and stream CRCs and xz's header, block-check and index CRCs.
TEST(checksummed_formats_detect_corruption) {
    for (size_t i = 0; i < N_VECTORS; i++) {
        const vector_t *v = &k_vectors[i];
        if ((v->codec != CODEC_BZIP2 && v->codec != CODEC_XZ) || v->enc_len > EXHAUSTIVE_MAX || v->len == 0)
            continue;
        uint8_t *want = vec_gen(v->kind, v->len, v->seed);
        uint8_t *out = malloc(v->len);
        ASSERT_TRUE(out != NULL);
        for (size_t at = 0; at < v->enc_len; at++) {
            for (int bit = 0; bit < 8; bit += 3) {
                uint8_t *bad = dup_bytes(v->enc, v->enc_len);
                bad[at] ^= (uint8_t)(1u << bit);
                int64_t n = codec_decode((codec_id_t)v->codec, bad, v->enc_len, out, v->len);
                // A flip may land in bits the decoder never reads (the final
                // byte's padding, a stream's reserved bits): then the data
                // must still be right.
                if (n >= 0) {
                    if (n != (int64_t)v->len || memcmp(out, want, v->len) != 0)
                        note(v, "an undetected corruption");
                    ASSERT_EQ_INT((int)v->len, (int)n);
                    ASSERT_TRUE(memcmp(out, want, v->len) == 0);
                }
                free(bad);
            }
        }
        free(out);
        free(want);
    }
}

// ---- format details ------------------------------------------------------

// The vector of a data set in a given encoding.
static const vector_t *find(const char *name) {
    for (size_t i = 0; i < N_VECTORS; i++)
        if (strcmp(k_vectors[i].name, name) == 0)
            return &k_vectors[i];
    fprintf(stderr, "[FAIL] no vector %s\n", name);
    exit(1);
}

// Two streams back to back decode as their concatenation, as `bzip2 -c a b`
// and `xz -c a b` write them; xz allows zero padding between, in fours.
TEST(concatenated_streams) {
    const char *pairs[][2] = {
        {"text3k/bz9", "runs/bz1"       },
        {"small/xz",   "text3k/xz_crc32"}
    };
    for (size_t p = 0; p < 2; p++) {
        const vector_t *a = find(pairs[p][0]), *b = find(pairs[p][1]);
        for (size_t pad = 0; pad <= (p ? 8u : 0u); pad += 4) {
            size_t n = a->enc_len + pad + b->enc_len;
            uint8_t *cat = calloc(1, n);
            ASSERT_TRUE(cat != NULL);
            memcpy(cat, a->enc, a->enc_len);
            memcpy(cat + a->enc_len + pad, b->enc, b->enc_len);
            uint8_t *wa = vec_gen(a->kind, a->len, a->seed), *wb = vec_gen(b->kind, b->len, b->seed);
            uint8_t *out = malloc(a->len + b->len);
            ASSERT_TRUE(out != NULL);
            int64_t got = codec_decode((codec_id_t)a->codec, cat, n, out, a->len + b->len);
            ASSERT_EQ_INT((int)(a->len + b->len), (int)got);
            ASSERT_TRUE(memcmp(out, wa, a->len) == 0 && memcmp(out + a->len, wb, b->len) == 0);
            free(out);
            free(wa);
            free(wb);
            free(cat);
        }
    }
    // Padding that is not a multiple of four is not stream padding.
    const vector_t *a = find("small/xz");
    uint8_t *odd = calloc(1, a->enc_len + 3);
    ASSERT_TRUE(odd != NULL);
    memcpy(odd, a->enc, a->enc_len);
    uint8_t out[256];
    ASSERT_TRUE(codec_xz_decompress(odd, a->enc_len + 3, out, sizeof(out)) < 0);
    free(odd);
}

// A bzip2 block in the "randomised" form (bzip2 before 0.9.5) is refused as
// unsupported, not decoded wrongly.  Its flag is the bit after the 48-bit
// block magic and the 32-bit block CRC: byte 14, top bit.
TEST(bzip2_randomised_block_is_unsupported) {
    const vector_t *v = find("text3k/bz9");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    ASSERT_TRUE(b[4] == 0x31 && b[5] == 0x41); // the block magic follows "BZh9"
    ASSERT_TRUE((b[14] & 0x80) == 0);
    b[14] |= 0x80;
    uint8_t *out = malloc(v->len);
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_bzip2_decompress(b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// An xz block whose filter is not LZMA2 (here delta, 0x03) is unsupported;
// with the header CRC left stale it is a checksum error first.
TEST(xz_other_filters_are_unsupported) {
    const vector_t *v = find("text3k/xz");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    // Stream header (12 bytes), then the block header: size, flags (no
    // optional sizes in this encoder's output), filter id 0x21.
    ASSERT_TRUE(b[13] == 0x00 && b[14] == 0x21);
    size_t hsize = ((size_t)b[12] + 1) * 4;
    b[14] = 0x03;
    uint8_t *out = malloc(v->len);
    ASSERT_EQ_INT(CODEC_ERR_CHECKSUM, (int)codec_xz_decompress(b, v->enc_len, out, v->len));
    uint32_t crc = codec_crc32(0, b + 12, hsize - 4);
    for (int k = 0; k < 4; k++)
        b[12 + hsize - 4 + k] = (uint8_t)(crc >> (8 * k));
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_xz_decompress(b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// The encodings cover every LZFSE block kind: stored, LZVN and v2.
TEST(lzfse_block_kinds_are_covered) {
    ASSERT_TRUE(memcmp(find("random/lzfse")->enc, "bvx-", 4) == 0);
    ASSERT_TRUE(memcmp(find("text3k/lzfse")->enc, "bvxn", 4) == 0);
    ASSERT_TRUE(memcmp(find("text/lzfse")->enc, "bvx2", 4) == 0);
    ASSERT_TRUE(memcmp(find("zeros/lzfse")->enc, "bvx2", 4) == 0);
    // The unpacked-header form never appears in a stream: refused.
    static const uint8_t v1[16] = {'b', 'v', 'x', '1'};
    uint8_t out[16];
    ASSERT_EQ_INT(CODEC_ERR_UNSUPPORTED, (int)codec_lzfse_decompress(v1, sizeof(v1), out, sizeof(out)));
    // An unknown magic is malformed.
    static const uint8_t junk[8] = {'b', 'v', 'x', '?'};
    ASSERT_EQ_INT(CODEC_ERR_DATA, (int)codec_lzfse_decompress(junk, sizeof(junk), out, sizeof(out)));
}

// The .lzma header's decoded size bounds the output; a stream claiming more
// than the capacity is an overflow before anything is decoded.
TEST(lzma_alone_size_field) {
    const vector_t *v = find("text3k/lzma");
    uint8_t *b = dup_bytes(v->enc, v->enc_len);
    uint8_t *out = malloc(v->len);
    // Python writes the size as unknown (all ones), so the end marker ends it.
    ASSERT_TRUE(b[5] == 0xFF && b[12] == 0xFF);
    ASSERT_EQ_INT((int)v->len, (int)codec_lzma_alone_decompress(b, v->enc_len, out, v->len));
    // Stated exactly: decodes to that size (the end marker is not reached).
    for (int k = 0; k < 8; k++)
        b[5 + k] = (uint8_t)((uint64_t)v->len >> (8 * k));
    ASSERT_EQ_INT((int)v->len, (int)codec_lzma_alone_decompress(b, v->enc_len, out, v->len));
    // Stated larger than the buffer.
    b[5] = (uint8_t)(b[5] + 1);
    ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)codec_lzma_alone_decompress(b, v->enc_len, out, v->len));
    free(out);
    free(b);
}

// ---- checksums -----------------------------------------------------------

// The published check values: each algorithm over "123456789" (Adler-32
// over "Wikipedia", its usual example), and chaining over a split.
TEST(checksums_match_check_values) {
    const char *s = "123456789";
    ASSERT_TRUE(codec_crc32(0, s, 9) == 0xCBF43926u); // CRC-32/ISO-HDLC
    ASSERT_TRUE(codec_crc32_msb(0, s, 9) == 0xFC891918u); // CRC-32/BZIP2
    ASSERT_TRUE(codec_crc64(0, s, 9) == 0x995DC9BBDF1939FAull); // CRC-64/XZ
    ASSERT_TRUE(codec_adler32(1, "Wikipedia", 9) == 0x11E60398u);
    for (size_t k = 0; k <= 9; k++) {
        ASSERT_TRUE(codec_crc32(codec_crc32(0, s, k), s + k, 9 - k) == 0xCBF43926u);
        ASSERT_TRUE(codec_crc32_msb(codec_crc32_msb(0, s, k), s + k, 9 - k) == 0xFC891918u);
        ASSERT_TRUE(codec_crc64(codec_crc64(0, s, k), s + k, 9 - k) == 0x995DC9BBDF1939FAull);
    }
    ASSERT_TRUE(codec_crc32(0, NULL, 0) == 0 && codec_crc64(0, NULL, 0) == 0);
}

// ---- dispatch ------------------------------------------------------------

TEST(dispatch_names_and_errors) {
    ASSERT_TRUE(strcmp(codec_name(CODEC_BZIP2), "bzip2") == 0);
    ASSERT_TRUE(strcmp(codec_name(CODEC_LZFSE), "lzfse") == 0);
    ASSERT_TRUE(strcmp(codec_name(CODEC_XZ), "xz") == 0);
    ASSERT_TRUE(strcmp(codec_name((codec_id_t)99), "?") == 0);
    uint8_t out[8];
    ASSERT_EQ_INT(CODEC_ERR_ARG, (int)codec_decode((codec_id_t)99, out, 1, out, sizeof(out)));
    // Stored: exactly the bytes, and no more than fit.
    ASSERT_EQ_INT(3, (int)codec_decode(CODEC_COPY, (const uint8_t *)"abc", 3, out, sizeof(out)));
    ASSERT_TRUE(memcmp(out, "abc", 3) == 0);
    ASSERT_EQ_INT(CODEC_ERR_OVERFLOW, (int)codec_decode(CODEC_COPY, (const uint8_t *)"abc", 3, out, 2));
    // Every code has its own text.
    for (int rc = CODEC_ERR_ARG; rc <= CODEC_ERR_DATA; rc++)
        for (int other = rc + 1; other <= CODEC_ERR_DATA; other++)
            ASSERT_TRUE(strcmp(codec_strerror(rc), codec_strerror(other)) != 0);
    // NULL input is an argument error for every decoder.
    for (int id = CODEC_DEFLATE; id < CODEC_COUNT; id++)
        ASSERT_EQ_INT(CODEC_ERR_ARG, (int)codec_decode((codec_id_t)id, NULL, 4, out, sizeof(out)));
}

int main(void) {
    RUN(vectors_decode_exactly);
    RUN(truncation_fails_cleanly);
    RUN(corruption_is_contained);
    RUN(checksummed_formats_detect_corruption);
    RUN(concatenated_streams);
    RUN(bzip2_randomised_block_is_unsupported);
    RUN(xz_other_filters_are_unsupported);
    RUN(lzfse_block_kinds_are_covered);
    RUN(lzma_alone_size_field);
    RUN(checksums_match_check_values);
    RUN(dispatch_names_and_errors);
    fprintf(stderr, "All codec tests passed (%zu vectors)\n", N_VECTORS);
    return 0;
}
